   782  bool Mac::ShouldSendBeacon(void) const
   783  {
   784      bool shouldSend = false;
   785
   786      VerifyOrExit(mEnabled);
   787
   788      shouldSend = IsBeaconEnabled();
   789
   790  #if OPENTHREAD_CONFIG_ENABLE_BEACON_RSP_WHEN_JOINABLE
   791      if (!shouldSend)
   792      {
   793          // When `ENABLE_BEACON_RSP_WHEN_JOINABLE` feature is enabled,
   794          // the device should transmit IEEE 802.15.4 Beacons in response
   795          // to IEEE 802.15.4 Beacon Requests even while the device is not
   796          // router capable and detached (i.e., `IsBeaconEnabled()` is
   797          // false) but only if it is in joinable state (unsecure port
   798          // list is not empty).
   799
   800          uint8_t numUnsecurePorts;
   801
   802          GetNetif().GetIp6Filter().GetUnsecurePorts(numUnsecurePorts);
   803          shouldSend = (numUnsecurePorts != 0);
   804      }
   805  #endif
   806
   807  exit:
   808      return shouldSend;
   809  }
