   811  void Mac::ProcessTransmitAesCcm(Frame &aFrame, const ExtAddress *aExtAddress)
   812  {
   813      uint32_t       frameCounter = 0;
   814      uint8_t        securityLevel;
   815      uint8_t        nonce[kNonceSize];
   816      uint8_t        tagLength;
   817      Crypto::AesCcm aesCcm;
   818      otError        error;
   819
   820      aFrame.GetSecurityLevel(securityLevel);
   821      aFrame.GetFrameCounter(frameCounter);
   822
   823      GenerateNonce(*aExtAddress, frameCounter, securityLevel, nonce);
   824
   825      aesCcm.SetKey(aFrame.GetAesKey(), 16);
   826      tagLength = aFrame.GetFooterLength() - Frame::kFcsSize;
   827
   828      error = aesCcm.Init(aFrame.GetHeaderLength(), aFrame.GetPayloadLength(), tagLength, nonce, sizeof(nonce));
   829      assert(error == OT_ERROR_NONE);
   830
   831      aesCcm.Header(aFrame.GetHeader(), aFrame.GetHeaderLength());
   832      aesCcm.Payload(aFrame.GetPayload(), aFrame.GetPayload(), aFrame.GetPayloadLength(), true);
   833      aesCcm.Finalize(aFrame.GetFooter(), &tagLength);
   834  }
