  1707      uint8_t commandId;
  1708
  1709      aFrame.GetCommandId(commandId);
  1710
  1711      switch (commandId)
  1712      {
  1713      case Frame::kMacCmdBeaconRequest:
  1714          mCounters.mRxBeaconRequest++;
  1715          otLogInfoMac("Received Beacon Request");
